head.script:
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};

scwin.trigger1_onclick = function(e) {
	widgetContainer1.removeTitleClass("widget0", "w2widget_orange");
};

scwin.trigger2_onclick = function(e) {
	widgetContainer1.setTitleClass("widget0", "w2widget_orange");
};

scwin.checkVal1 = function() {
	return window.getComputedStyle(scwin.__getDom($p.id + 'widgetContainer1_widget0_title')).getPropertyValue('background-color') == 'rgb(255, 165, 0)';
};

scwin.checkVal2 = function() {
	return window.getComputedStyle(scwin.__getDom($p.id + 'widgetContainer1_widget0_title')).getPropertyValue('background-color') != 'rgb(255, 165, 0)';
};

scwin.onpageload2 = function() {
	widgetContainer1.addWidgets({
		id: "widget0",
		title: "widget0",
		src: "/sample/common_link/widgetContainer_WPF-1476_(WSQ-2446)_widget.xml",
		scope: true,
		x: 0,
		y: 0,
		unitWidth: 1,
		unitHeight: 1
	});
	widgetContainer1.addWidgets({
		id: "widget1",
		title: "widget1",
		titleClass: "w2widget_blue",
		src: null,
		scope: true,
		x: 0,
		y: 1,
		unitWidth: 1,
		unitHeight: 1
	});
	widgetContainer1.addWidgets({
		id: "widget2",
		title: "widget2",
		src: "/sample/common_link/widgetContainer_WPF-1476_(WSQ-2446)_widget.xml",
		scope: true,
		x: 0,
		y: 2,
		unitWidth: 1,
		unitHeight: 1
	});
};
